let mySeed; 

let nonStop = true;

function setup() {
	createCanvas(1000,1000);
	rectMode(CENTER);
	ellipseMode(CENTER);
	colorMode(HSB, 360, 100, 100,100);
	mySeed = floor(random(1,1000000));
}

function draw() {

 randomSeed(mySeed);

 //fill(0);

 ///addBlur();

 let mySize = 800;

 if (!nonStop)
 { 
	 // noLoop() removed for animation 
 }
	let xx = width/2;
	let yy = height/2;
	{
		fill(90);
		push();
		translate(xx,yy);
		//strokeWeight(5);
		//circle(0,0,mySize*0.95);
		let signo = random([-1,1]);
		rotate(signo*0.01*frameCount)
		for(i=1.7;i < 4.5;i+=0.80)
		{
			drawCircles(-mySize/6.7,0,mySize/i);
			drawCircles(mySize/6.7,0,mySize/i);
			drawCircles(0,0,mySize/i);
		}
		pop();
	}

}

function drawCircles(x,y,mySize)
{
	//stroke(0);
	noStroke();
	let dir = random([-1,1]);
	let rphase = random(0,2*PI);
	let freq = random(0.01,0.025);
	let col1 = color(generateColor());
	fill(col1);
	let temp;
	let d = 1;
	if (d < 10)
	{
	  temp = frameCount;
	}else
	{
		temp = 1;
	}
	var xx = x + mySize/2*cos(dir*freq*temp + rphase);
	var yy = y + mySize/2*sin(dir*freq*temp + rphase);
	//strokeWeight(1);
	stroke(0);
	strokeWeight(1);
	line(x,y,xx,yy);
	noStroke();
	circle(xx,yy,mySize/9);
	let col2 = color(generateColor());
	col2.setAlpha(random(100,100));
	fill(col2);
	circle(x,y,mySize/4);
	fill(100);
	circle(xx,yy,mySize/25 + 0*sin(0.01*frameCount));
}

function addBlur() {
	drawingContext.shadowOffsetX = -2;
	drawingContext.shadowOffsetY = -2;
	drawingContext.shadowBlur = 5;
	drawingContext.shadowColor = 'black';
}


function generateColor(){
	let myColor = color(random(colors));
	//myColor.setAlpha(random(0,100));
	return myColor;
}

